package org.example.leave.dao;

import org.example.leave.util.DBConnection;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class LeaveApplicationDAO {
    private static final String INSERT_SQL = "INSERT INTO leave_applications (employee_name, employee_id, department, leave_type, leave_days, reason, approval_message) VALUES (?, ?, ?, ?, ?, ?, ?)";

    public void save(String employeeName, String employeeId, String department, String leaveType,
                     int leaveDays, String reason, String approvalMessage) throws SQLException {
        Connection connection = null;
        try {
            connection = DBConnection.getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_SQL)) {
            statement.setString(1, employeeName.trim());
            statement.setString(2, employeeId.trim());
            statement.setString(3, department.trim());
            statement.setString(4, leaveType.trim());
            statement.setInt(5, leaveDays);
            statement.setString(6, reason.trim());
            statement.setString(7, approvalMessage);
            statement.executeUpdate();
            }
        } finally {
            DBConnection.closeConnection(connection);
        }
    }
}

package org.example.leave.dao;

import org.example.leave.util.DBConnection;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.SQLException;

public class LeaveApplicationDAO {
    private static final String INSERT_SQL = "INSERT INTO leave_applications " +
            "(employee_name, employee_id, department, leave_type, leave_days, reason, approval_message) " +
            "VALUES (?, ?, ?, ?, ?, ?, ?)";

    public void save(String employeeName, String employeeId, String department, String leaveType,
                     int leaveDays, String reason, String approvalMessage) throws SQLException {
        Connection connection = null;
        try {
            connection = DBConnection.getConnection();
            try (PreparedStatement statement = connection.prepareStatement(INSERT_SQL)) {
                statement.setString(1, employeeName.trim());
                statement.setString(2, employeeId.trim());
                statement.setString(3, department.trim());
                statement.setString(4, leaveType.trim());
                statement.setInt(5, leaveDays);
                statement.setString(6, reason.trim());
                statement.setString(7, approvalMessage);
                statement.executeUpdate();
            }
        } finally {
            if (connection != null) {
                connection.close();
            }
        }
    }
}

package org.example.leave.servlet;

import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.example.leave.dao.LeaveApplicationDAO;
import org.example.leave.util.RequestErrorUtil;
import org.example.leave.util.ValidationUtil;

import java.io.IOException;

public class LeaveServlet extends HttpServlet {
    private transient LeaveApplicationDAO leaveApplicationDAO;

    @Override
    public void init() throws ServletException {
        leaveApplicationDAO = new LeaveApplicationDAO();
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        RequestDispatcher dispatcher = request.getRequestDispatcher("/leave.jsp");
        dispatcher.forward(request, response);
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String employeeName = request.getParameter("employeeName");
        String employeeId = request.getParameter("employeeId");
        String department = request.getParameter("department");
        String leaveType = request.getParameter("leaveType");
        String leaveDaysText = request.getParameter("leaveDays");
        String reason = request.getParameter("reason");

        int leaveDays = ValidationUtil.parseLeaveDays(leaveDaysText);
        String validationError = ValidationUtil.validate(employeeName, employeeId, department, leaveType, leaveDays, reason);
        if (validationError != null) {
            RequestErrorUtil.redirectWithError(request, response, validationError);
            return;
        }

        String approvalMessage = ValidationUtil.approvalMessage(leaveDays);

        try {
            leaveApplicationDAO.save(employeeName, employeeId, department, leaveType, leaveDays, reason, approvalMessage);
        } catch (Exception exception) {
            RequestErrorUtil.redirectWithError(request, response, "Unable to submit leave request right now");
            return;
        }

        request.setAttribute("employeeName", employeeName.trim());
        request.setAttribute("employeeId", employeeId.trim());
        request.setAttribute("department", department.trim());
        request.setAttribute("leaveType", leaveType.trim());
        request.setAttribute("leaveDays", leaveDays);
        request.setAttribute("reason", reason.trim());
        request.setAttribute("approvalMessage", approvalMessage);

        RequestDispatcher dispatcher = request.getRequestDispatcher("/review.jsp");
        dispatcher.forward(request, response);
    }

    @Override
    public void destroy() {
        leaveApplicationDAO = null;
        getServletContext().log("LeaveServlet destroyed");
    }
}

package org.example.leave.servlet;

import jakarta.servlet.RequestDispatcher;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServlet;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import jakarta.servlet.http.HttpSession;
import org.example.leave.dao.LeaveApplicationDAO;
import org.example.leave.util.RequestErrorUtil;
import org.example.leave.util.ValidationUtil;

import java.io.IOException;
import java.sql.SQLException;

public class LeaveServlet extends HttpServlet {
    private transient LeaveApplicationDAO leaveApplicationDAO;

    @Override
    public void init() {
        leaveApplicationDAO = new LeaveApplicationDAO();
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        HttpSession session = request.getSession(false);
        if (session != null) {
            Object formError = session.getAttribute("formError");
            if (formError != null) {
                request.setAttribute("formError", formError);
                session.removeAttribute("formError");
            }
        }

        RequestDispatcher dispatcher = request.getRequestDispatcher("/leave.jsp");
        try {
            dispatcher.forward(request, response);
        } catch (ServletException e) {
            throw new IOException(e);
        }
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws ServletException, IOException {
        String employeeName = request.getParameter("employeeName");
        String employeeId = request.getParameter("employeeId");
        String department = request.getParameter("department");
        String leaveType = request.getParameter("leaveType");
        String leaveDaysText = request.getParameter("leaveDays");
        String reason = request.getParameter("reason");

        int leaveDays = ValidationUtil.parseLeaveDays(leaveDaysText);
        String validationError = ValidationUtil.validate(employeeName, employeeId, department, leaveType, leaveDays, reason);
        if (validationError != null) {
            RequestErrorUtil.redirectWithError(request, response, validationError);
            return;
        }

        String approvalMessage = ValidationUtil.approvalMessage(leaveDays);

        try {
            leaveApplicationDAO.save(employeeName, employeeId, department, leaveType, leaveDays, reason, approvalMessage);
        } catch (SQLException exception) {
            getServletContext().log("Failed to save leave request", exception);
            RequestErrorUtil.redirectWithError(request, response,
                    "Unable to submit leave request right now. Please check the database connection and try again.");
            return;
        }

        request.setAttribute("employeeName", employeeName.trim());
        request.setAttribute("employeeId", employeeId.trim());
        request.setAttribute("department", department.trim());
        request.setAttribute("leaveType", leaveType.trim());
        request.setAttribute("leaveDays", leaveDays);
        request.setAttribute("reason", reason.trim());
        request.setAttribute("approvalMessage", approvalMessage);

        RequestDispatcher dispatcher = request.getRequestDispatcher("/review.jsp");
        dispatcher.forward(request, response);
    }

    @Override
    public void destroy() {
        leaveApplicationDAO = null;
        getServletContext().log("LeaveServlet destroyed");
    }
}

package org.example.leave.util;

import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;

public class DBConnection {
    private static final String URL = "jdbc:mysql://localhost:3306/employee_leave_system";
    private static final String USER = "root";
    private static final String PASSWORD = "Abhishek@1137";
    private static final String DB_DRIVER = "com.mysql.cj.jdbc.Driver";

    static {
        try {
            Class.forName(DB_DRIVER);
        } catch (ClassNotFoundException e) {
            System.err.println("Failed to load JDBC driver: " + e.getMessage());
        }
    }

    public static Connection getConnection() throws SQLException {
        try {
            Connection conn = DriverManager.getConnection(URL, USER, PASSWORD);
            System.out.println("Database connection established successfully!");
            return conn;
        } catch (SQLException e) {
            System.err.println("Database connection failed: " + e.getMessage());
            throw e;
        }
    }

    public static void closeConnection(Connection conn) {
        if (conn != null) {
            try {
                conn.close();
                System.out.println("Database connection closed successfully!");
            } catch (SQLException e) {
                System.err.println("Failed to close connection: " + e.getMessage());
            }
        }
    }
}

package org.example.leave.util;

import java.io.IOException;
import java.io.InputStream;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.SQLException;
import java.util.Properties;

public class DBConnection {
    private static final String DB_DRIVER = "com.mysql.cj.jdbc.Driver";
    private static final String DEFAULT_URL = "jdbc:mysql://localhost:3306/employee_leave_system?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC";
    private static final String DEFAULT_USER = "root";
    private static final String DEFAULT_PASSWORD = "Abhishek@1137";

    private static final String URL;
    private static final String USER;
    private static final String PASSWORD;

    static {
        Properties properties = new Properties();
        try (InputStream input = DBConnection.class.getClassLoader().getResourceAsStream("db.properties")) {
            if (input != null) {
                properties.load(input);
            }
        } catch (IOException e) {
            System.err.println("Failed to load db.properties: " + e.getMessage());
        }

        URL = resolveValue("DB_URL", properties.getProperty("db.url"), DEFAULT_URL);
        USER = resolveValue("DB_USER", properties.getProperty("db.user"), DEFAULT_USER);
        PASSWORD = resolveValue("DB_PASSWORD", properties.getProperty("db.password"), DEFAULT_PASSWORD);

        try {
            Class.forName(DB_DRIVER);
        } catch (ClassNotFoundException e) {
            System.err.println("Failed to load JDBC driver: " + e.getMessage());
        }
    }

    private DBConnection() {
    }

    private static String resolveValue(String envKey, String propertyValue, String defaultValue) {
        String envValue = System.getenv(envKey);
        if (envValue != null && !envValue.trim().isEmpty()) {
            return envValue.trim();
        }
        if (propertyValue != null && !propertyValue.trim().isEmpty()) {
            return propertyValue.trim();
        }
        return defaultValue;
    }

    public static Connection getConnection() throws SQLException {
        try {
            Connection conn = DriverManager.getConnection(URL, USER, PASSWORD);
            System.out.println("Database connection established successfully!");
            return conn;
        } catch (SQLException e) {
            System.err.println("Database connection failed: " + e.getMessage());
            throw e;
        }
    }

}

package org.example.leave.util;

public final class ValidationUtilTest {

    public static void main(String[] args) {
        shouldReturnErrorWhenEmployeeNameIsBlank();
        shouldReturnErrorWhenLeaveDaysAreOutOfRange();
        shouldReturnErrorWhenReasonIsTooShort();
        shouldReturnMinusOneForInvalidLeaveDays();
        shouldReturnNullForValidInput();
        System.out.println("ValidationUtilTest passed");
    }

    private static void shouldReturnErrorWhenEmployeeNameIsBlank() {
        assertEquals("Employee Name not empty",
                ValidationUtil.validate("", "E001", "HR", "Sick Leave", 2, "Need leave for medical reasons"));
    }

    private static void shouldReturnErrorWhenLeaveDaysAreOutOfRange() {
        assertEquals("Leave Days must be between 1 and 10",
                ValidationUtil.validate("John", "E001", "HR", "Sick Leave", 11, "Need leave for medical reasons"));
    }

    private static void shouldReturnErrorWhenReasonIsTooShort() {
        assertEquals("Reason must have at least 10 characters",
                ValidationUtil.validate("John", "E001", "HR", "Sick Leave", 2, "short"));
    }

    private static void shouldReturnMinusOneForInvalidLeaveDays() {
        assertEquals(-1, ValidationUtil.parseLeaveDays("abc"));
    }

    private static void shouldReturnNullForValidInput() {
        assertNull(ValidationUtil.validate("John", "E001", "HR", "Sick Leave", 2, "Need leave for medical reasons"));
    }

    private static void assertEquals(Object expected, Object actual) {
        if (expected == null ? actual != null : !expected.equals(actual)) {
            throw new AssertionError("Expected: " + expected + ", Actual: " + actual);
        }
    }

    private static void assertNull(Object actual) {
        if (actual != null) {
            throw new AssertionError("Expected null but was: " + actual);
        }
    }
}
